import json, os, re, subprocess
from pathlib import Path
from urllib.parse import urlsplit
from dotenv import dotenv_values
root=Path.cwd(); token=dotenv_values(root/'.local/hermes-lab/home/.env',interpolate=False).get('SLACK_BOT_TOKEN')
assert token and token.startswith('xoxb-')
env=os.environ.copy(); env.pop('SLACK_USER_TOKEN',None); env['SLACK_BOT_TOKEN']=token
allowed={'auth.test','conversations.info','conversations.replies'}
def call(method,**params):
    assert method in allowed
    proc=subprocess.run(['slack','api',method,*[k+'='+str(v) for k,v in params.items()],'--skip-update','--no-color'],env=env,capture_output=True,text=True)
    try:data=json.loads(proc.stdout)
    except Exception:raise SystemExit('Unexpected Slack CLI response; suppressed.')
    if proc.returncode or not data.get('ok'):raise SystemExit('Slack read failed: '+str(data.get('error','unknown_error')))
    return data
auth=call('auth.test')
assert (auth.get('team_id'),auth.get('user_id'))==('T0C6J1XCDE0','U0C5Z1ZQHQX'),'Identity mismatch'
link='https://clanker-global.slack.com/archives/D0C6EAXPKEE/p1791494671575999'
parts=urlsplit(link).path.split('/'); channel=parts[2]; digits=parts[3][1:]; parent=digits[:-6]+'.'+digits[-6:]
info=call('conversations.info',channel=channel); ch=info['channel']
assert ch.get('is_im') is True and ch.get('user')=='U0C688SF7DZ','DM participant mismatch'
print(json.dumps({'auth.test':{k:auth.get(k) for k in ('ok','team_id','user_id')},'conversations.info':{k:ch.get(k) for k in ('id','is_im','user')},'parent_ts':parent}))
pages=[]; messages=[]; cursor=''; seen=set()
while True:
    args={'channel':channel,'ts':parent,'limit':100}
    if cursor:args['cursor']=cursor
    page=call('conversations.replies',**args); pages.append(page); messages.extend(page.get('messages',[]))
    cursor=(page.get('response_metadata') or {}).get('next_cursor','').strip()
    if not cursor:
        assert not page.get('has_more'),'Incomplete pagination'
        break
    assert cursor not in seen,'Repeated cursor'; seen.add(cursor)
out=root/'.local/slack-signin-duplicate-20261009'; out.mkdir(mode=0o700,parents=True,exist_ok=True)
p=out/'thread.json'; p.write_text(json.dumps({'auth':auth,'channel':info,'pages':pages},indent=2)); p.chmod(0o600)
def safe(value):
