    if isinstance(value,list):return [safe(x) for x in value]
    if isinstance(value,dict):return {k:safe(v) for k,v in value.items() if k not in {'value','trigger_id'}}
    return value
print(json.dumps({'pagination_complete':True,'pages':len(pages),'messages':len(messages),'replies':len(messages)-1}))
for m in messages:print(json.dumps(safe({k:m[k] for k in ('ts','thread_ts','user','bot_id','text','reply_count','blocks','attachments') if k in m})))
